#!/usr/bin/env python3\n\"\"\"\nSubstance-over-Slop Asset Audit Script\nDaily verification of asset traceability and integrity.\n\"\"\"\n\nfrom hashlib import sha256\nimport json\nimport os\nfrom pathlib import Path\nfrom app.extractors.authentic_snes_extractor import validate_rom_integrity\nfrom app.config import CONFIG\n\nASSETS_PATH = Path(CONFIG.assets_path)\nROM_SOURCE_PATH = Path(CONFIG.rom_source_path)\nMANIFEST_PATH = ASSETS_PATH / \"extraction_manifest.json\"\nAUDIT_LOG = Path(\"OUTPUT\") / \"validation\" / \"asset_audit.log\"\n\nclass AssetAudit:\n    def __init__(self):\n        self.issues = []\n        self.verified = 0\n        self.total = 0\n\n    def run_daily_audit(self):\n        \"\"\"Run full audit: ROMs, extractions, integration.\"\"\"\n        self.audit_rom_sources()\n        self.audit_extractions()\n        self.generate_report()\n\n    def audit_rom_sources(self):\n        \"\"\"Verify ROM library integrity.\"\"\"\n        for rom_path in ROM_SOURCE_PATH.glob(\"*.{sfc,smc}\"):\n            self.total += 1\n            try:\n                with open(rom_path, 'rb') as f:\n                    rom_data = f.read()\n                    rom_hash = sha256(rom_data).hexdigest()\n                # Check against known good hashes (load from manifest or db)\n                if self._check_known_hash(rom_path.name, rom_hash):\n                    self.verified += 1\n                else:\n                    self.issues.append(f\"ROM {rom_path.name} hash mismatch: {rom_hash}\")\n            except Exception as e:\n                self.issues.append(f\"ROM {rom_path} error: {e}\")\n\n    def audit_extractions(self):\n        \"\"\"Verify extracted assets trace to ROMs.\"\"\"\n        if MANIFEST_PATH.exists():\n            with open(MANIFEST_PATH) as f:\n                manifest = json.load(f)\n            for entry in manifest['assets']:\n                self.total += 1\n                rom_id = entry.get('source_rom')\n                if self._verify_extraction_trace(rom_id, entry):\n                    self.verified += 1\n                else:\n                    self.issues.append(f\"Asset {entry['id']} trace broken for ROM {rom_id}\")\n        else:\n            self.issues.append(\"No extraction manifest found.\")\n\n    def _check_known_hash(self, rom_name, computed_hash):\n        # Placeholder: load known hashes from separate file or compute on first run\n        # For now, assume all are verified if no issues\n        return True  # Implement full check\n\n    def _verify_extraction_trace(self, rom_id, entry):\n        # Check if extracted data matches ROM bank/offset\n        return validate_rom_integrity(entry)  # Use existing validator\n\n    def generate_report(self):\n        report = {\n            'timestamp': datetime.now().isoformat(),\n            'total_assets': self.total,\n            'verified': self.verified,\n            'issues': self.issues,\n            'substance_score': (self.verified / self.total * 100) if self.total > 0 else 0,\n        }\n        report_path = Path(\"OUTPUT\") / \"morning_reports\" / f\"audit_{datetime.now().strftime('%Y%m%d')}.json\"\n        with open(report_path, 'w') as f:\n            json.dump(report, f, indent=2)\n\n        with open(AUDIT_LOG, 'a') as f:\n            f.write(f\"{json.dumps(report)}\\n\")\n\nif __name__ == \"__main__\":\n    audit = AssetAudit()\n    audit.run_daily_audit()\n    print(f\"Audit complete: {audit.verified}/{audit.total} verified ({report['substance_score']:.1f}%)\")\n
